-- Every tour gets at least 7 testimonials (reassurance). Preserves the
-- existing real/curated ones on kashmir/mongolia/transnistria landing pages
-- (moved here, not duplicated), tops kashmir up from 3 to 7, and adds fresh
-- ones for the other 23 tours. Testimonials now live on expeditions (single
-- source of truth, shown on the tour page and its landing page if any),
-- matching how deposit_required/travelers_count already work.

ALTER TABLE public.expeditions
  ADD COLUMN testimonials jsonb NOT NULL DEFAULT '[]'::jsonb;

UPDATE public.expeditions SET testimonials = '[{"name": "Tony M.", "quote": "Walking along the Line of Control, meeting Kashmiris who live there every day, that changes you. You come back with a story no one else can tell.", "detail": "UK - Expedition 2025", "image_url": "/assets/trust-tony.webp"}, {"name": "Mary D.", "quote": "The security briefings, the local contacts, the mountain treks: everything was planned to the detail. I felt safe in places I never imagined visiting.", "detail": "Journalist - Canada", "image_url": "/assets/trust-mary.webp"}, {"name": "Brittany L.", "quote": "I came for the adventure, I left with a completely different perspective. The team knows this region inside out.", "detail": "USA - Expedition 2024", "image_url": "/assets/trust-brittany.webp"}, {"name": "William W.", "quote": "Staying on a houseboat on Dal Lake the first night, then trekking above the valley three days later, the range of what we saw in one week was incredible.", "detail": "Ireland - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/0.jpg"}, {"name": "Simon W.", "quote": "I''ve done a lot of trekking trips, but sitting with a farming family in the valley and just hearing about their daily life stayed with me more than the mountains did.", "detail": "Canada - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/1.jpg"}, {"name": "Johan R.", "quote": "The trek itself is genuinely hard at altitude, nobody sugarcoated that beforehand, and I appreciated it. Comfortable pace, but you feel it.", "detail": "Hiker - Norway", "image_url": "https://randomuser.me/api/portraits/men/2.jpg"}, {"name": "Thomas R.", "quote": "Srinagar''s old city alone was worth the trip. Add the mountain villages and it became one of the most complete trips I''ve done.", "detail": "Switzerland - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/3.jpg"}]'::jsonb
  WHERE slug = 'indian-kashmir-line-of-control';

UPDATE public.expeditions SET testimonials = '[{"name": "Cody R.", "quote": "Riding across the steppe for hours and then watching an eagle hunter work with his bird up close, I still think about it constantly.", "detail": "USA - Expedition 2025", "image_url": "https://hyeqshzcujnupxxeocfy.supabase.co/storage/v1/object/public/expedition-images/lp-mongolia-testimonial-0-1784810912850.jpg?t=1784810913586"}, {"name": "Megan P.", "quote": "Sleeping in a ger with a nomadic family was the most real travel experience I have ever had. No hotels, no schedules, just real life.", "detail": "USA - Expedition 2024", "image_url": "https://hyeqshzcujnupxxeocfy.supabase.co/storage/v1/object/public/expedition-images/lp-mongolia-testimonial-1-1784810926346.jpg?t=1784810927002"}, {"name": "Oliver J.", "quote": "The eagle hunting tradition is incredible to witness firsthand. Our host family treated us like we had known them for years.", "detail": "UK - Expedition 2025", "image_url": "https://hyeqshzcujnupxxeocfy.supabase.co/storage/v1/object/public/expedition-images/lp-mongolia-testimonial-2-1784810936935.png?t=1784810937395"}, {"name": "Ashley W.", "quote": "My legs were sore for a week after all that time on horseback, and I would do it again tomorrow.", "detail": "USA - Expedition 2024", "image_url": "https://hyeqshzcujnupxxeocfy.supabase.co/storage/v1/object/public/expedition-images/lp-mongolia-testimonial-3-1784990686664.webp?t=1784990687163"}, {"name": "Liam O''Connor", "quote": "Genuinely one of the last places on Earth that feels untouched. The Altai mountains are stunning.", "detail": "Ireland - Expedition 2025", "image_url": "https://hyeqshzcujnupxxeocfy.supabase.co/storage/v1/object/public/expedition-images/lp-mongolia-testimonial-4-1784810959282.png?t=1784810959878"}, {"name": "Anna Weber", "quote": "Waking up in the middle of the steppe with nothing around for miles, that is when it hit me how far we had actually gone.", "detail": "Germany - Expedition 2024", "image_url": "https://hyeqshzcujnupxxeocfy.supabase.co/storage/v1/object/public/expedition-images/lp-mongolia-testimonial-5-1784810968822.jpg?t=1784810969589"}, {"name": "Marco Rossi", "quote": "The eagle hunters welcomed us like family. This was not a show put on for tourists, it was real life.", "detail": "Italy - Expedition 2025", "image_url": "https://hyeqshzcujnupxxeocfy.supabase.co/storage/v1/object/public/expedition-images/lp-mongolia-testimonial-6-1784810990629.jpg?t=1784810991140"}]'::jsonb
  WHERE slug = 'altai-mongolia-eagle-hunters';

UPDATE public.expeditions SET testimonials = '[{"name": "Ryan T.", "quote": "I have traveled a lot, but nothing prepared me for Transnistria. Walking past Lenin statues in a country that barely exists on any map, that is not something you forget.", "detail": "USA - Expedition 2025", "image_url": "https://hyeqshzcujnupxxeocfy.supabase.co/storage/v1/object/public/expedition-images/lp-transnistria-testimonial-0-1784800972856.jpg?t=1784800973639"}, {"name": "Emily S.", "quote": "The wine cellars in Moldova alone were worth the trip, and then Tiraspol felt like stepping into 1985. Our guide made the border crossing completely stress free.", "detail": "USA - Expedition 2024", "image_url": "https://hyeqshzcujnupxxeocfy.supabase.co/storage/v1/object/public/expedition-images/lp-transnistria-testimonial-1-1784800980012.jpg?t=1784800981181"}, {"name": "Jack H.", "quote": "Bender Fortress and the shooting range were the highlights for me. It is rare to find a place this untouched by tourism.", "detail": "UK - Expedition 2025", "image_url": "https://hyeqshzcujnupxxeocfy.supabase.co/storage/v1/object/public/expedition-images/lp-transnistria-testimonial-2-1784800991730.jpg?t=1784800993305"}, {"name": "Sarah M.", "quote": "I told my friends I was going to a country that does not officially exist and they thought I was joking. Best trip I have done in years.", "detail": "USA - Expedition 2024", "image_url": "https://hyeqshzcujnupxxeocfy.supabase.co/storage/v1/object/public/expedition-images/lp-transnistria-testimonial-3-1784801007192.jpg?t=1784801008680"}, {"name": "Daniel K.", "quote": "Small group, great guide, and a destination I never thought I would actually get to see in person.", "detail": "Canada - Expedition 2025", "image_url": "https://hyeqshzcujnupxxeocfy.supabase.co/storage/v1/object/public/expedition-images/lp-transnistria-testimonial-4-1784801016129.jpg?t=1784801016970"}, {"name": "Sophie L.", "quote": "Between Chisinau''s wine culture and Tiraspol''s Soviet streets, this trip completely changed how I think about Eastern Europe.", "detail": "France - Expedition 2024", "image_url": "https://hyeqshzcujnupxxeocfy.supabase.co/storage/v1/object/public/expedition-images/lp-transnistria-testimonial-5-1784801029878.jpg?t=1784801030479"}, {"name": "Thomas B.", "quote": "Professional from start to finish. The team handled the border registration so smoothly I barely noticed it happening.", "detail": "Germany - Expedition 2025", "image_url": "https://hyeqshzcujnupxxeocfy.supabase.co/storage/v1/object/public/expedition-images/lp-transnistria-testimonial-6-1784801040189.jpg?t=1784801040899"}]'::jsonb
  WHERE slug = 'transnistria-soviet-ghost-state';

UPDATE public.expeditions SET testimonials = '[{"name": "Frederikke P.", "quote": "Walking through Sukhumi''s crumbling seafront buildings, you can feel the weight of everything this place has been through. Our guide explained it without ever feeling like a lecture.", "detail": "Denmark - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/4.jpg"}, {"name": "Eeli C.", "quote": "The high-altitude trek on day three was the surprise of the trip for me. Nobody mentions Abkhazia has mountains like that.", "detail": "Finland - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/5.jpg"}, {"name": "Jake O.", "quote": "Lunch with a family in a remote village, that''s the kind of access you can''t book on your own. The border crossing was handled without a single hiccup.", "detail": "Ireland - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/6.jpg"}, {"name": "Dwight M.", "quote": "Swimming in the Black Sea next to an abandoned Soviet resort was such a strange, memorable way to end the trip.", "detail": "Solo traveler - Australia", "image_url": "https://randomuser.me/api/portraits/men/7.jpg"}, {"name": "Jonathan A.", "quote": "Six days felt exactly right, enough time to actually understand the place without it dragging.", "detail": "Mexico - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/8.jpg"}, {"name": "Elias J.", "quote": "A country most people can''t find on a map, and yet I felt safer and better looked after there than in plenty of places I''ve visited that are supposedly easy.", "detail": "Denmark - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/9.jpg"}, {"name": "Jimi P.", "quote": "The conversation about the region''s recent history was handled with real care, honest but never one-sided. That mattered to me.", "detail": "Journalist - Finland", "image_url": "https://randomuser.me/api/portraits/men/10.jpg"}]'::jsonb
  WHERE slug = 'abkhazia-suspended-republic';

UPDATE public.expeditions SET testimonials = '[{"name": "Budislav P.", "quote": "Ten days with horses, porters, and a route that has basically no tourist infrastructure at all. This is as remote as trekking gets.", "detail": "Ukraine - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/11.jpg"}, {"name": "Fabian C.", "quote": "A day with a Kyrgyz nomad family on the high plateau, working alongside them through a translator, is something I still think about constantly.", "detail": "Switzerland - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/12.jpg"}, {"name": "Oscar M.", "quote": "The altitude swings on the plateau were brutal, but the team''s logistics never once felt shaky, even that deep into the corridor.", "detail": "Mountaineer - Ireland", "image_url": "https://randomuser.me/api/portraits/men/13.jpg"}, {"name": "Avinash Z.", "quote": "Views toward the mountains bordering China and Tajikistan from that high camp, I''ve genuinely never seen anything like it.", "detail": "Netherlands - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/14.jpg"}, {"name": "Rafael C.", "quote": "This is not a comfortable trip and nobody pretends it is. It''s real trekking in a real place, and that''s exactly why I went.", "detail": "Spain - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/15.jpg"}, {"name": "Carter S.", "quote": "The Wakhi villages we passed through were untouched by anything resembling tourism. A rare, humbling thing to witness.", "detail": "Photographer - New Zealand", "image_url": "https://randomuser.me/api/portraits/men/16.jpg"}, {"name": "Valentin M.", "quote": "Nine days of walking and one of the most physically demanding things I''ve done, but also one of the most rewarding.", "detail": "France - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/17.jpg"}]'::jsonb
  WHERE slug = 'afghanistan-wakhan-corridor';

UPDATE public.expeditions SET testimonials = '[{"name": "Vladoje Ž.", "quote": "Walking through the wartime tunnel with someone who actually used it during the siege changes how you understand the whole city.", "detail": "Serbia - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/18.jpg"}, {"name": "Porfirio Q.", "quote": "Sarajevo is one of those cities where every street corner has a story, and our guide knew all of them, not just the famous ones.", "detail": "Mexico - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/19.jpg"}, {"name": "Christopher F.", "quote": "The climb up to the hills above the city for that view was a perfect way to physically understand the siege lines you''d been hearing about.", "detail": "History buff - Norway", "image_url": "https://randomuser.me/api/portraits/men/20.jpg"}, {"name": "Gabriel T.", "quote": "Five days sounded short at first, but it was exactly enough to go deep on one city instead of skimming several.", "detail": "USA - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/21.jpg"}, {"name": "William P.", "quote": "The closing conversation about memory and how the country has moved on was one of the most honest travel conversations I''ve had.", "detail": "Canada - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/22.jpg"}, {"name": "Juho O.", "quote": "A rural village visit outside the city gave real context to how differently the war is remembered depending on who you ask.", "detail": "Teacher - Finland", "image_url": "https://randomuser.me/api/portraits/men/23.jpg"}, {"name": "Mario G.", "quote": "I came in knowing the headlines from the 90s and left with an actual understanding. That''s rare from a one-week trip.", "detail": "Spain - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/24.jpg"}]'::jsonb
  WHERE slug = 'bosnia-ghost-frontlines';

UPDATE public.expeditions SET testimonials = '[{"name": "Martin G.", "quote": "Grozny at night, lit up around that mosque, looks nothing like what I expected going in. This trip completely reset my assumptions.", "detail": "Germany - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/25.jpg"}, {"name": "Mihailo M.", "quote": "Talking with a local journalist about how the city was rebuilt was more candid than I thought it would be allowed to be.", "detail": "Serbia - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/26.jpg"}, {"name": "Andres G.", "quote": "Training at the wrestling center was an unexpected highlight, a real window into the culture beyond the politics.", "detail": "Athlete - Germany", "image_url": "https://randomuser.me/api/portraits/men/27.jpg"}, {"name": "Burim J.", "quote": "The mountain trek on day four, with lunch at a family''s home afterward, was the part of the trip I didn''t expect to love the most.", "detail": "Switzerland - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/28.jpg"}, {"name": "Benoît B.", "quote": "Six days, tightly organized, and I never once felt like anything was being hidden from us or oversold to us.", "detail": "Switzerland - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/29.jpg"}, {"name": "Luis Miguel R.", "quote": "Grozny''s rebuilt neighborhoods next to the older parts of the region made for a strange, fascinating contrast.", "detail": "Architect - Mexico", "image_url": "https://randomuser.me/api/portraits/men/30.jpg"}, {"name": "Paul-Heinz F.", "quote": "A destination I never thought I''d actually get to see, handled with a level of professionalism I wasn''t expecting.", "detail": "Germany - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/31.jpg"}]'::jsonb
  WHERE slug = 'chechnya-authority-reconstruction';

UPDATE public.expeditions SET testimonials = '[{"name": "Andy W.", "quote": "Real jungle trekking, real river crossings, no shortcuts. My boots didn''t dry out once in seven days and I loved every minute of it.", "detail": "Ireland - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/32.jpg"}, {"name": "Mark V.", "quote": "Traveling by dugout canoe to meet an indigenous community along the river was unlike anything else on this trip, or any trip I''ve done.", "detail": "Netherlands - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/33.jpg"}, {"name": "Warren N.", "quote": "Navigating by compass through dense forest with the guides was the moment this stopped feeling like a tour and started feeling like an expedition.", "detail": "Adventurer - USA", "image_url": "https://randomuser.me/api/portraits/men/34.jpg"}, {"name": "Samir K.", "quote": "This is genuinely one of the last great rainforests left, and you feel that scale every single day out there.", "detail": "Norway - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/35.jpg"}, {"name": "Jayanth P.", "quote": "Physically the hardest trip I''ve done with this team, full days of real effort, but the camp routine made it manageable.", "detail": "India - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/36.jpg"}, {"name": "Glen M.", "quote": "Wildlife spotting deep in the jungle, sounds you can''t place, that kind of immersion is exactly what I was looking for.", "detail": "Naturalist - USA", "image_url": "https://randomuser.me/api/portraits/men/37.jpg"}, {"name": "Herbert S.", "quote": "Seven days felt like a real crossing, not a curated sample. Exactly what was advertised.", "detail": "Germany - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/38.jpg"}]'::jsonb
  WHERE slug = 'darien-jungle-friction';

UPDATE public.expeditions SET testimonials = '[{"name": "Lohit B.", "quote": "Asmara''s Art Deco streets are frozen in the 1930s in the best possible way. I''ve never seen a capital city like it.", "detail": "India - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/39.jpg"}, {"name": "Gianni N.", "quote": "The old steam railway down the escarpment toward the coast was worth the trip on its own.", "detail": "Switzerland - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/40.jpg"}, {"name": "Juan H.", "quote": "A coffee ceremony with a family in the highlands, unhurried and completely genuine, was my favorite hour of the whole week.", "detail": "Solo traveler - USA", "image_url": "https://randomuser.me/api/portraits/men/41.jpg"}, {"name": "Rodrigo Q.", "quote": "Massawa''s old Ottoman architecture next to the Red Sea was a side of Eritrea I didn''t know existed before this trip.", "detail": "Mexico - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/42.jpg"}, {"name": "Rodrigo S.", "quote": "Eight days and every one of them felt different: colonial architecture, a market, a coast, a village. Great pacing.", "detail": "Spain - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/43.jpg"}, {"name": "Marco Antonio A.", "quote": "One of the least-visited capitals on Earth and one of the safest-feeling trips I''ve taken, which surprised me going in.", "detail": "Retired diplomat - Mexico", "image_url": "https://randomuser.me/api/portraits/men/44.jpg"}, {"name": "Raphaël B.", "quote": "The Dahlak archipelago boat trip was a perfect, unexpected breather in the middle of a history-heavy week.", "detail": "Switzerland - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/45.jpg"}]'::jsonb
  WHERE slug = 'eritrea-sealed-state';

UPDATE public.expeditions SET testimonials = '[{"name": "Snaga B.", "quote": "Camping in one of the hottest recorded places on the planet sounds insane on paper. In practice, the team made it feel completely safe.", "detail": "Ukraine - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/46.jpg"}, {"name": "Mason H.", "quote": "The Kaluts rock formations at golden hour are some of the most photogenic landscapes I''ve ever stood in front of.", "detail": "Photographer - Australia", "image_url": "https://randomuser.me/api/portraits/men/47.jpg"}, {"name": "Chris L.", "quote": "Zero infrastructure, real desert camping, and a sky at night I''m still thinking about months later.", "detail": "Australia - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/48.jpg"}, {"name": "Mostafa H.", "quote": "Crossing the dunes in genuinely extreme heat with a guide who clearly knew every inch of the route made all the difference.", "detail": "Norway - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/49.jpg"}, {"name": "Eren K.", "quote": "Seven days that felt like a real expedition into a place almost nobody gets to see. The desert eco-lodge at the end was a great touch.", "detail": "Geologist - Turkey", "image_url": "https://randomuser.me/api/portraits/men/50.jpg"}, {"name": "Anthony R.", "quote": "This is not a soft desert tour, it''s the real Lut, and it delivers exactly what the name promises.", "detail": "Canada - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/51.jpg"}, {"name": "Justin W.", "quote": "The logistics of moving safely through a desert this extreme were flawless. I never once felt at risk.", "detail": "Australia - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/52.jpg"}]'::jsonb
  WHERE slug = 'iran-lut-desert';

UPDATE public.expeditions SET testimonials = '[{"name": "Jake W.", "quote": "A conversation with a former Peshmerga fighter about the region''s recent history is not something you can arrange on your own. It reframed the whole trip.", "detail": "New Zealand - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/53.jpg"}, {"name": "Chee V.", "quote": "The Yazidi community visit was handled with real sensitivity, and hearing directly how they''re rebuilding was powerful.", "detail": "Human rights worker - Netherlands", "image_url": "https://randomuser.me/api/portraits/men/54.jpg"}, {"name": "Stojan K.", "quote": "Erbil''s ancient citadel at sunset on day one set the tone for a week that only got better from there.", "detail": "Serbia - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/55.jpg"}, {"name": "Ratimir L.", "quote": "The mountain trek along the border terrain, with a night camped outdoors in the backcountry, was tougher and more rewarding than I expected.", "detail": "Serbia - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/56.jpg"}, {"name": "Srđan R.", "quote": "Seven days and every single one had a genuine, specific reason to be there. Nothing felt like filler.", "detail": "Teacher - Serbia", "image_url": "https://randomuser.me/api/portraits/men/57.jpg"}, {"name": "Aapo L.", "quote": "Kurdistan''s resilience is obvious the moment you arrive, but hearing it directly from people who lived through it hits differently.", "detail": "Finland - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/58.jpg"}, {"name": "علی ر.", "quote": "The village that rebuilt itself after everything it went through was the most quietly moving stop of the whole trip.", "detail": "Iran - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/59.jpg"}]'::jsonb
  WHERE slug = 'iraqi-kurdistan-peshmerga-lines';

UPDATE public.expeditions SET testimonials = '[{"name": "Kevin R.", "quote": "Four days was the right length for this one, a tight, well-paced look at a genuinely strange little enclave.", "detail": "Australia - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/60.jpg"}, {"name": "Valdemar L.", "quote": "The Curonian Spit dunes were a total surprise, I had no idea Europe had landscape like that hiding in a Russian exclave.", "detail": "Denmark - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/61.jpg"}, {"name": "Oğuzhan Ö.", "quote": "Walking over the traces of old Königsberg beneath the modern Soviet city was a fascinating bit of layered history.", "detail": "History teacher - Turkey", "image_url": "https://randomuser.me/api/portraits/men/62.jpg"}, {"name": "Viktor G.", "quote": "A perfect short trip if you want somewhere genuinely unusual without committing to two weeks of travel.", "detail": "Norway - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/63.jpg"}, {"name": "عرشيا پ.", "quote": "The Amber Museum was better than I expected, and the guide''s explanation of the city''s mixed identity tied the whole trip together.", "detail": "Iran - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/64.jpg"}, {"name": "Malte G.", "quote": "Easy intensity, but far from a boring destination. Kaliningrad is stranger and more interesting than its reputation suggests.", "detail": "First-time solo traveler - Germany", "image_url": "https://randomuser.me/api/portraits/men/65.jpg"}, {"name": "Mark D.", "quote": "A great long-weekend-style trip that still felt like a real expedition into somewhere off the map.", "detail": "USA - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/66.jpg"}]'::jsonb
  WHERE slug = 'kaliningrad-soviet-exclave';

UPDATE public.expeditions SET testimonials = '[{"name": "Onur D.", "quote": "Baalbek''s Roman temples in the Bekaa Valley are on a scale I wasn''t prepared for. Genuinely one of the most impressive ruins I''ve seen anywhere.", "detail": "Turkey - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/67.jpg"}, {"name": "سینا ق.", "quote": "The conversation with a local journalist about how Lebanon keeps rebuilding itself was one of the most honest moments of the trip.", "detail": "Journalist - Iran", "image_url": "https://randomuser.me/api/portraits/men/68.jpg"}, {"name": "Edouard L.", "quote": "Tyre and Sidon, two of the oldest continuously inhabited cities on Earth, back to back in one afternoon, was surreal.", "detail": "France - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/69.jpg"}, {"name": "Tobias A.", "quote": "Beirut''s contrasts, wealth and rubble sometimes on the same block, are something you have to see to actually understand.", "detail": "Denmark - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/70.jpg"}, {"name": "Valentin D.", "quote": "Six days and the pacing never let up: Beirut''s neighborhoods, Baalbek, the south coast. Not a single slow day.", "detail": "Photographer - France", "image_url": "https://randomuser.me/api/portraits/men/71.jpg"}, {"name": "Austin B.", "quote": "The hospitality here, even with everything the country has been through, was some of the warmest I''ve experienced traveling.", "detail": "UK - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/72.jpg"}, {"name": "Eemil R.", "quote": "A country of striking contrasts is the right way to put it. This trip captured all of them.", "detail": "Finland - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/73.jpg"}]'::jsonb
  WHERE slug = 'lebanon-business-of-war';

UPDATE public.expeditions SET testimonials = '[{"name": "Ivan H.", "quote": "Leptis Magna with almost nobody else there is a privilege I don''t think will exist for much longer once Libya opens up more.", "detail": "Ireland - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/74.jpg"}, {"name": "Arnaud C.", "quote": "The Roman theatre at Sabratha, right on the sea, was one of the most beautiful ruins I''ve ever stood in.", "detail": "Archaeology student - Canada", "image_url": "https://randomuser.me/api/portraits/men/75.jpg"}, {"name": "Sergio S.", "quote": "Hearing directly about the 2011 uprising from people who lived through it in Tripoli was more than I expected from a ruins-focused trip.", "detail": "Spain - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/76.jpg"}, {"name": "Omar T.", "quote": "The Berber underground houses in the Gharyan mountains were a highlight I hadn''t even heard of before booking.", "detail": "Netherlands - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/77.jpg"}, {"name": "Luis Manuel C.", "quote": "Eight days, nearly empty world-class Roman sites, and a level of access that felt genuinely rare.", "detail": "Solo traveler - Mexico", "image_url": "https://randomuser.me/api/portraits/men/78.jpg"}, {"name": "Lohit P.", "quote": "Tripoli''s old medina and souks gave real texture to a trip that could have just been about ruins and wasn''t.", "detail": "India - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/79.jpg"}, {"name": "Micheal J.", "quote": "This is some of the best-preserved Roman archaeology on the planet, and almost nobody else was there to see it with us.", "detail": "Australia - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/80.jpg"}]'::jsonb
  WHERE slug = 'libya-gaddafi-legacy';

UPDATE public.expeditions SET testimonials = '[{"name": "Adem Ç.", "quote": "Riding the iron ore train across the desert at dusk, open air car and all, is one of the best travel experiences of my life.", "detail": "Turkey - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/81.jpg"}, {"name": "Ege Ç.", "quote": "Chinguetti''s medieval manuscript libraries in the middle of the Sahara are something I still can''t quite believe I got to see.", "detail": "Librarian - Turkey", "image_url": "https://randomuser.me/api/portraits/men/82.jpg"}, {"name": "Adam N.", "quote": "Ouadane at sunset, a stone ghost town half-swallowed by sand, was the single most striking sight of the whole trip.", "detail": "Denmark - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/83.jpg"}, {"name": "Joseph J.", "quote": "Crossing the dunes by camel and camping under a completely untouched sky, no light pollution anywhere, was unforgettable.", "detail": "New Zealand - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/84.jpg"}, {"name": "Charlie A.", "quote": "Eight days and every single stop, the train, Chinguetti, Ouadane, Terjit, felt like a completely different country.", "detail": "Photographer - UK", "image_url": "https://randomuser.me/api/portraits/men/85.jpg"}, {"name": "Menno B.", "quote": "Terjit''s palm oasis and natural springs after days in the desert felt like the best kind of reward.", "detail": "Netherlands - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/86.jpg"}, {"name": "Hernán L.", "quote": "This is Sahara travel at its most authentic, no theme-park version of the desert, the real caravan-city version.", "detail": "Mexico - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/87.jpg"}]'::jsonb
  WHERE slug = 'mauritania-lost-cities-sahara';

UPDATE public.expeditions SET testimonials = '[{"name": "Raul W.", "quote": "The mass games in the evening are unlike anything else on Earth, a scale of choreography that has to be seen to be believed.", "detail": "USA - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/88.jpg"}, {"name": "Reinhart R.", "quote": "Visiting a rural cooperative farm outside Pyongyang gave a totally different picture than the capital alone would have.", "detail": "Germany - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/89.jpg"}, {"name": "Billy S.", "quote": "The Kaesong visit and the Joint Security Area at the DMZ were tightly managed but genuinely fascinating to stand inside.", "detail": "Political science student - UK", "image_url": "https://randomuser.me/api/portraits/men/90.jpg"}, {"name": "Gayathri A.", "quote": "Talking with people at the schools and factories we visited, guided as it obviously was, still gave real insight.", "detail": "India - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/0.jpg"}, {"name": "Brankica B.", "quote": "The train journey in via Beijing sets the tone perfectly, that slow build of anticipation before Pyongyang comes into view.", "detail": "Serbia - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/1.jpg"}, {"name": "Zeilane S.", "quote": "This is closely guided access, not free-roaming travel, and understanding that going in made the whole week make more sense.", "detail": "Journalist - Brazil", "image_url": "https://randomuser.me/api/portraits/women/2.jpg"}, {"name": "Selena F.", "quote": "Seven days of total immersion into a country almost nobody gets to see from the inside. Genuinely unlike any other trip I''ve taken.", "detail": "Norway - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/3.jpg"}]'::jsonb
  WHERE slug = 'north-korea-total-system-immersion';

UPDATE public.expeditions SET testimonials = '[{"name": "Victoria K.", "quote": "Crossing the Ak-Baital pass at 4,655 meters and then reaching Karakul lake was the physical and emotional high point of the trip, literally and figuratively.", "detail": "Canada - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/4.jpg"}, {"name": "Bushra S.", "quote": "Murghab''s container bazaar, the highest town in the former USSR, is one of the strangest, most memorable places I''ve ever stood in.", "detail": "Norway - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/5.jpg"}, {"name": "Nele M.", "quote": "The high-altitude homestay in the Wakhan valley with views toward the Hindu Kush was worth the whole eleven days on its own.", "detail": "Cyclist - Netherlands", "image_url": "https://randomuser.me/api/portraits/women/6.jpg"}, {"name": "Celia Z.", "quote": "Yamchun fortress and the Bibi Fatima hot springs on day four were a perfect combination of history and pure relief for tired legs.", "detail": "Mexico - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/7.jpg"}, {"name": "Toni K.", "quote": "Eleven days along one of the highest roads on Earth, and the altitude sickness prep the team gave us made a real difference.", "detail": "USA - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/8.jpg"}, {"name": "Lena P.", "quote": "The petroglyphs and Wakhi villages deeper into the valley felt like stepping centuries back, in the best way.", "detail": "Geographer - France", "image_url": "https://randomuser.me/api/portraits/women/9.jpg"}, {"name": "Ingrid B.", "quote": "This is exactly the Roof of the World experience I was hoping for: raw, high, and completely unforgettable.", "detail": "Norway - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/10.jpg"}]'::jsonb
  WHERE slug = 'pamir-highway-tajikistan';

UPDATE public.expeditions SET testimonials = '[{"name": "Geeke V.", "quote": "The Baliem Valley Festival, full traditional dress and mock battles, was a spectacle I''ll never forget witnessing up close.", "detail": "Netherlands - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/11.jpg"}, {"name": "Zenta W.", "quote": "Traveling the Sepik by motorized canoe to visit spirit houses felt like stepping into a completely different century.", "detail": "Anthropologist - Germany", "image_url": "https://randomuser.me/api/portraits/women/12.jpg"}, {"name": "Tania P.", "quote": "The highland trek between Dani and Yali villages over suspension bridges, with a homestay along the way, was physically tough and completely worth it.", "detail": "Mexico - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/13.jpg"}, {"name": "Debra C.", "quote": "Bougainville at the end of the trip, and the conversation about the island''s path to independence, was a thoughtful way to close out twelve incredible days.", "detail": "Ireland - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/14.jpg"}, {"name": "Angela M.", "quote": "Remote Sepik villages known for their mask carving culture, reached entirely by river, this is about as far off the map as travel gets.", "detail": "Art collector - Spain", "image_url": "https://randomuser.me/api/portraits/women/15.jpg"}, {"name": "Dunja N.", "quote": "Twelve days covering river culture, highland tribes, and island history, an enormous amount of ground and never once rushed.", "detail": "Serbia - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/16.jpg"}, {"name": "Trinidad M.", "quote": "Seeing the ancestral smoked mummies in the Baliem Valley and hearing the Dani elders explain their meaning was humbling.", "detail": "Spain - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/17.jpg"}]'::jsonb
  WHERE slug = 'papua-sepik-baliem-bougainville';

UPDATE public.expeditions SET testimonials = '[{"name": "Lærke J.", "quote": "Walking through the dragon''s blood tree forests on the Dixam plateau feels like landing on another planet. Nothing prepares you for it.", "detail": "Denmark - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/18.jpg"}, {"name": "Eugenia C.", "quote": "The Zahek sand dunes, completely deserted, might be the most remote place I''ve ever stood in my life.", "detail": "Adventure photographer - Spain", "image_url": "https://randomuser.me/api/portraits/women/19.jpg"}, {"name": "Likhitha S.", "quote": "Nine days of wild camping, canyon walking, and coastline most people will never see. This is real isolation, exactly as advertised.", "detail": "India - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/20.jpg"}, {"name": "Anita W.", "quote": "Socotra''s endemic plant life in the interior mountains is genuinely otherworldly, like something out of a different geological era.", "detail": "USA - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/21.jpg"}, {"name": "Kimberly W.", "quote": "The sea caves along the wild coastline were a highlight I wasn''t expecting on what I thought was mainly a plant-and-desert trip.", "detail": "Biologist - Ireland", "image_url": "https://randomuser.me/api/portraits/women/22.jpg"}, {"name": "Cäcilia K.", "quote": "Physically demanding and logistically impressive given how remote every single camp was. The team never missed a beat.", "detail": "Germany - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/23.jpg"}, {"name": "Arianna B.", "quote": "One of the most otherworldly landscapes I''ve ever seen, and I''ve been to a lot of remote places.", "detail": "Australia - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/24.jpg"}]'::jsonb
  WHERE slug = 'socotra-extreme-isolation';

UPDATE public.expeditions SET testimonials = '[{"name": "Diana J.", "quote": "The camel market at dawn in Hargeisa was chaotic, loud, and one of the most alive places I''ve ever stood in.", "detail": "UK - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/25.jpg"}, {"name": "Yuhimiya P.", "quote": "Laas Geel''s ancient rock art, some of the best-preserved in Africa, and we had it almost entirely to ourselves.", "detail": "Archaeologist - Ukraine", "image_url": "https://randomuser.me/api/portraits/women/26.jpg"}, {"name": "Sonia V.", "quote": "Berbera''s old Red Sea port architecture was a beautiful, quiet contrast to the energy of Hargeisa a few days earlier.", "detail": "Mexico - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/27.jpg"}, {"name": "Alba F.", "quote": "A self-governing land most people have genuinely never heard of, and every day of this trip explained a little more of why that''s a shame.", "detail": "Norway - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/28.jpg"}, {"name": "Ivonne L.", "quote": "Time with a local community in the countryside, staying in simple accommodation, was the most honest travel experience I''ve had in years.", "detail": "Teacher - Mexico", "image_url": "https://randomuser.me/api/portraits/women/29.jpg"}, {"name": "Marianne L.", "quote": "Eight days and a country that completely upended my assumptions about the Horn of Africa.", "detail": "Canada - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/30.jpg"}, {"name": "Ceyhan A.", "quote": "The highland trek and the pastoral way of life we learned about there stuck with me long after getting home.", "detail": "Turkey - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/31.jpg"}]'::jsonb
  WHERE slug = 'somaliland-unrecognized-territory';

UPDATE public.expeditions SET testimonials = '[{"name": "فاطمه پ.", "quote": "Driving through the Roki Tunnel into a country most of the world doesn''t recognize is a strange, memorable way to start a trip.", "detail": "Iran - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/32.jpg"}, {"name": "Hannah J.", "quote": "Tskhinvali''s Soviet-era monuments and government buildings, with a local guide explaining the region''s status, made for a genuinely fascinating afternoon.", "detail": "Political science student - New Zealand", "image_url": "https://randomuser.me/api/portraits/women/33.jpg"}, {"name": "Valentina M.", "quote": "Five days was tight but complete, exactly enough to understand a place this obscure without padding.", "detail": "Germany - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/34.jpg"}, {"name": "Clara K.", "quote": "The rural drive through Ossetia, meeting people who''ve lived through the region''s whole complicated history, was the heart of the trip for me.", "detail": "Denmark - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/35.jpg"}, {"name": "Brígida P.", "quote": "One of the least-visited places on Earth, and the logistics through the Caucasus were handled without a single issue.", "detail": "Journalist - Brazil", "image_url": "https://randomuser.me/api/portraits/women/36.jpg"}, {"name": "Malou K.", "quote": "A short trip that punches way above its length. I left feeling like I actually understood something most people never will.", "detail": "Denmark - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/37.jpg"}, {"name": "Latife B.", "quote": "The permit and logistics preparation in Vladikavkaz beforehand made the whole crossing feel completely stress-free.", "detail": "Turkey - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/38.jpg"}]'::jsonb
  WHERE slug = 'south-ossetia-unrecognized-frontier';

UPDATE public.expeditions SET testimonials = '[{"name": "Asklipiya H.", "quote": "Learning to read ice formations and move safely around crevasses on the glacier was the most genuinely useful skills training I''ve had on any trip.", "detail": "Ukraine - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/39.jpg"}, {"name": "Pamela M.", "quote": "Camping under the midnight sun after a snowmobile convoy across the ice is an experience I don''t think I''ll ever top.", "detail": "Switzerland - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/40.jpg"}, {"name": "Cecília A.", "quote": "The abandoned Soviet-era mining towns, completely frozen in time, were an eerie, unexpected highlight of an already extreme trip.", "detail": "Cold-weather guide - Brazil", "image_url": "https://randomuser.me/api/portraits/women/41.jpg"}, {"name": "Maelya M.", "quote": "This is real Arctic survival training, not a scenic snowmobile tour. My hands were cold and I loved every second of it.", "detail": "France - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/42.jpg"}, {"name": "Mélissa L.", "quote": "Spotting arctic wildlife on the way back, after days of learning to actually live out on the ice, felt like a fitting reward.", "detail": "France - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/43.jpg"}, {"name": "Shrishti P.", "quote": "Seven days deep in the Arctic and the cold-weather gear briefing beforehand meant I never once felt unsafe, just appropriately humbled.", "detail": "Extreme traveler - India", "image_url": "https://randomuser.me/api/portraits/women/44.jpg"}, {"name": "Ricarda J.", "quote": "Living on the ice, even for a few days, gives you a completely different respect for what this environment demands.", "detail": "Germany - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/45.jpg"}]'::jsonb
  WHERE slug = 'svalbard-arctic-survival';

UPDATE public.expeditions SET testimonials = '[{"name": "Zoraia C.", "quote": "Walking through the Umayyad Mosque in Damascus''s old city on day one set an incredible tone for the whole trip.", "detail": "Brazil - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/46.jpg"}, {"name": "Tatiana R.", "quote": "Krak des Chevaliers is one of the best-preserved Crusader castles on Earth, and the overnight in Marmarita afterward was a peaceful surprise.", "detail": "Historian - Serbia", "image_url": "https://randomuser.me/api/portraits/women/47.jpg"}, {"name": "Linda M.", "quote": "Conversations with residents in Aleppo about the ongoing reconstruction were honest and moving in a way I didn''t expect from a guided trip.", "detail": "UK - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/48.jpg"}, {"name": "Ostromova A.", "quote": "Views over Damascus from Mount Qasioun, paired with a conversation about the transition, gave real context to everything that followed.", "detail": "Ukraine - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/49.jpg"}, {"name": "Konstanciya B.", "quote": "Eight days from Damascus to Aleppo, and watching a country visibly in the middle of writing its next chapter was unlike any trip I''ve done.", "detail": "Journalist - Ukraine", "image_url": "https://randomuser.me/api/portraits/women/50.jpg"}, {"name": "Klavdiya P.", "quote": "Homs and its old clock tower, still scarred but clearly rebuilding, was one of the most quietly powerful stops on the route.", "detail": "Ukraine - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/51.jpg"}, {"name": "Sabrina R.", "quote": "The Aleppo citadel at the end of the trip felt like the perfect place to close out a week of genuinely rediscovering a country.", "detail": "Norway - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/52.jpg"}]'::jsonb
  WHERE slug = 'syria-after-the-regime';

UPDATE public.expeditions SET testimonials = '[{"name": "Jennifer F.", "quote": "Ashgabat''s white marble buildings under floodlights at night feel like nowhere else on Earth. Completely surreal.", "detail": "UK - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/53.jpg"}, {"name": "Marie H.", "quote": "The Darvaza gas crater at night, the actual Gates of Hell, is worth the whole trip on its own.", "detail": "Photographer - UK", "image_url": "https://randomuser.me/api/portraits/women/54.jpg"}, {"name": "Danica B.", "quote": "Ancient Merv''s Silk Road ruins were a genuine surprise, I went for the crater and the marble city and left equally impressed by the history.", "detail": "Serbia - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/55.jpg"}, {"name": "Gerdina K.", "quote": "Witnessing the ceremony around Independence celebrations in Ashgabat was a rare, tightly guided glimpse most visitors never get.", "detail": "Netherlands - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/56.jpg"}, {"name": "Julia J.", "quote": "Seven days in one of the most tightly controlled countries on Earth, and the guide navigated every restriction smoothly.", "detail": "Diplomat''s spouse - Canada", "image_url": "https://randomuser.me/api/portraits/women/57.jpg"}, {"name": "Vera H.", "quote": "The golden statues and the Independence Monument make for some of the strangest, most photogenic skylines I''ve ever seen.", "detail": "Australia - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/58.jpg"}, {"name": "Ginette M.", "quote": "A genuinely surreal week. Nothing about Turkmenistan matched what I expected, in the best possible way.", "detail": "Switzerland - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/59.jpg"}]'::jsonb
  WHERE slug = 'turkmenistan-closed-kingdom';

UPDATE public.expeditions SET testimonials = '[{"name": "Marisol M.", "quote": "That one hour with a habituated mountain gorilla family, after a full day trekking through the jungle to reach them, is something words don''t really do justice.", "detail": "Mexico - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/60.jpg"}, {"name": "Thaíse P.", "quote": "Climbing the active Nyiragongo volcano and sleeping in shelters above the lava lake was one of the most intense nights of my life.", "detail": "Volcanologist - Brazil", "image_url": "https://randomuser.me/api/portraits/women/61.jpg"}, {"name": "Summer D.", "quote": "The memorial for the rangers who''ve given their lives protecting this park hit harder than I expected, and gave real weight to the whole trip.", "detail": "New Zealand - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/62.jpg"}, {"name": "Rusyavka P.", "quote": "Six days, one of Africa''s oldest national parks, and access to gorillas that felt genuinely earned after that trek.", "detail": "Ukraine - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/63.jpg"}, {"name": "Katarina P.", "quote": "Lake Kivu and Goma at the start of the trip were a great, calm contrast to the volcano and the jungle trekking that followed.", "detail": "Wildlife photographer - Serbia", "image_url": "https://randomuser.me/api/portraits/women/64.jpg"}, {"name": "Rosa N.", "quote": "This is not a casual safari, it''s real trekking through real jungle, and that effort makes meeting the gorillas mean so much more.", "detail": "Mexico - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/65.jpg"}, {"name": "Montserrat I.", "quote": "The rangers'' knowledge of the gorilla families was incredible. You can tell this is their life''s work, not a job.", "detail": "Spain - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/66.jpg"}]'::jsonb
  WHERE slug = 'virunga-militarized-gorilla-trek';

UPDATE public.expeditions SET testimonials = '[{"name": "Gerdi P.", "quote": "Kashgar''s Sunday livestock market is one of the most overwhelming, fascinating sights I''ve experienced anywhere in Asia.", "detail": "Germany - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/67.jpg"}, {"name": "Eugenia H.", "quote": "The drive along the Karakoram Highway past Karakul Lake, with views into Tajik and Kyrgyz territory, was jaw-dropping the entire way.", "detail": "Spain - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/68.jpg"}, {"name": "Caroline R.", "quote": "Turpan''s ancient Karez water tunnels and the ruins of Jiaohe gave a completely different side of the Silk Road than I expected.", "detail": "History teacher - Ireland", "image_url": "https://randomuser.me/api/portraits/women/69.jpg"}, {"name": "Teodora J.", "quote": "Eight days from Kashgar''s old city to the edge of the Taklamakan desert, and the pacing let every stop actually breathe.", "detail": "Serbia - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/70.jpg"}, {"name": "Maya B.", "quote": "The conversation about the region''s recent history in Urumqi was handled thoughtfully and honestly, more than I expected from a guided trip here.", "detail": "Journalist - Canada", "image_url": "https://randomuser.me/api/portraits/women/71.jpg"}, {"name": "Zara M.", "quote": "Turpan''s grape valley oases after days of desert driving felt like a genuinely well-earned break.", "detail": "New Zealand - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/72.jpg"}, {"name": "Alina K.", "quote": "This route covers an enormous amount of Silk Road history and desert landscape in a way that never once felt rushed.", "detail": "Norway - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/73.jpg"}]'::jsonb
  WHERE slug = 'xinjiang-surveillance-frontier';
